unsigned checks=0,groups=0,comparisons=0;auto cases=nlohmann::json::array();
void require(bool good,const char* why){++checks;if(!good)throw std::runtime_error(why);}
std::vector<f::Channel> catalog(int maximum=128){return {{"density","kg/m^3","smoke",f::Domain::VisualReference,f::Merge::Sum,0,maximum,256}};}
s::Spec quiet(){s::Spec p;p.channels=s::Density;p.dimensions={4,4,4};p.cellMetres=.5f;p.originMetres={};p.maxDensity=10;p.densityDecay=p.cooling=p.fuelDecay=p.burnRate=p.buoyancy=p.smokeWeight=p.vorticity=0;p.maxSpeed=1;p.pressureIterations=4;p.macCormack=false;return p;}
f::LocalSpec local(const s::Spec& p,unsigned ratio,f::Cell origin,std::uint64_t source=1){f::LocalSpec out;out.owner="smoke";out.source=source;out.originFine=origin;out.dimensions={int(p.dimensions[0]),int(p.dimensions[1]),int(p.dimensions[2])};out.finePerWorld=ratio;out.channels={{0,f::ProjectionReduction::VolumeAverage}};return out;}
void initialize(Rig& rig,s::GpuSmokeFireSolver& solver,const s::Spec& spec,float density){auto state=s::initialState(spec);std::fill(state.scalars.begin(),state.scalars.end(),density);std::vector<s::CellInput> inputs(state.velocity.size());std::string error;require(solver.setInputs(inputs,error,&state),error.c_str());rig.begin();require(solver.step(rig.commands.p,rig.ticket(),0,1.f/120,error),error.c_str());rig.submit();}
struct Read {std::vector<int> values;std::uint64_t input=0,reconstructed=0;std::int64_t residual=0;std::array<unsigned,32> diagnostics{};};
Read read(Rig& rig,const std::shared_ptr<f::GpuLocalProjection>& projection){
    const auto b=projection->bindings();const auto p=b.planes.at(0);const std::uint64_t count=std::uint64_t(b.region.max.x-b.region.min.x)*(b.region.max.y-b.region.min.y)*(b.region.max.z-b.region.min.z),bytes=count*4;
    gpu_test::Com<ID3D12Resource> buffer;gpu_test::makeBuffer(rig.device.p,buffer,bytes+160,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);rig.begin();require(projection->markUsed(rig.ticket()),"Projection read fence");
    for(auto* resource:{p.values,p.metrics,b.diagnostics})gpu_test::transition(rig.commands.p,resource,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,D3D12_RESOURCE_STATE_COPY_SOURCE);
    rig.commands.p->CopyBufferRegion(buffer.p,0,p.values,0,bytes);rig.commands.p->CopyBufferRegion(buffer.p,bytes,p.metrics,0,32);rig.commands.p->CopyBufferRegion(buffer.p,bytes+32,b.diagnostics,0,128);
    for(auto* resource:{p.values,p.metrics,b.diagnostics})gpu_test::transition(rig.commands.p,resource,D3D12_RESOURCE_STATE_COPY_SOURCE,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);rig.submit();
    void* mapped=nullptr;D3D12_RANGE range{0,bytes+160};gpu_test::hr(buffer.p->Map(0,&range,&mapped),"Map validation projection");Read out;out.values.resize(count);auto* data=static_cast<const char*>(mapped);std::memcpy(out.values.data(),data,bytes);std::memcpy(&out.input,data+bytes,8);std::memcpy(&out.reconstructed,data+bytes+8,8);std::memcpy(&out.residual,data+bytes+16,8);std::memcpy(out.diagnostics.data(),data+bytes+32,128);D3D12_RANGE none{0,0};buffer.p->Unmap(0,&none);return out;
}
std::shared_ptr<f::GpuLocalProjection> project(Rig& rig,f::GpuLocalFields& fields,f::GpuLocalHandle handle,s::GpuSmokeFireSolver& solver,f::Tick publishTick){std::string error;rig.begin();require(fields.replaceScalar(handle,s::densityFieldInput(solver),rig.commands.p,rig.ticket(),error),error.c_str());auto out=fields.project(handle,publishTick,rig.commands.p,rig.ticket(),error);require(!!out,error.c_str());require(out->bindings().inputVersion==solver.buffers().version,"Producer version lost in projection");rig.submit();return out;}
struct Query {
    gpu_test::Com<ID3D12RootSignature> root;gpu_test::Com<ID3D12PipelineState> pipeline;
    explicit Query(Rig& rig){D3D12_ROOT_PARAMETER p[4]{};p[0].ParameterType=D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;p[0].Constants.Num32BitValues=28;p[1].ParameterType=p[2].ParameterType=D3D12_ROOT_PARAMETER_TYPE_SRV;p[2].Descriptor.ShaderRegister=1;p[3].ParameterType=D3D12_ROOT_PARAMETER_TYPE_UAV;D3D12_ROOT_SIGNATURE_DESC d{};d.NumParameters=4;d.pParameters=p;d.Flags=D3D12_ROOT_SIGNATURE_FLAG_CBV_SRV_UAV_HEAP_DIRECTLY_INDEXED;gpu_test::Com<ID3DBlob> bytes,errors;gpu_test::hr(D3D12SerializeRootSignature(&d,D3D_ROOT_SIGNATURE_VERSION_1,bytes.out(),errors.out()),"Serialize WF query root");gpu_test::hr(rig.device.p->CreateRootSignature(0,bytes.p->GetBufferPointer(),bytes.p->GetBufferSize(),IID_PPV_ARGS(root.out())),"Create WF query root");D3D12_COMPUTE_PIPELINE_STATE_DESC pd{};pd.pRootSignature=root.p;pd.CS={nativegpu::shaders::kFieldQuery.data,nativegpu::shaders::kFieldQuery.size};gpu_test::hr(rig.device.p->CreateComputePipelineState(&pd,IID_PPV_ARGS(pipeline.out())),"Create existing field query PSO");}
    std::vector<f::GpuFieldAnswer> run(Rig& rig,const std::shared_ptr<f::GpuVisualView>& view,const std::vector<f::GpuFieldQuery>& input,f::Tick tick){
        require(!!view,"Missing GPU WF view");const auto b=view->bindings();const auto inputBytes=input.size()*sizeof(f::GpuFieldQuery),bytes=input.size()*sizeof(f::GpuFieldAnswer);gpu_test::Com<ID3D12Resource> requests,output,read;
        gpu_test::makeBuffer(rig.device.p,requests,inputBytes,D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ);gpu_test::makeBuffer(rig.device.p,read,bytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);void* data=nullptr;D3D12_RANGE none{0,0};gpu_test::hr(requests.p->Map(0,&none,&data),"Map WF query requests");std::memcpy(data,input.data(),inputBytes);requests.p->Unmap(0,nullptr);
        D3D12_HEAP_PROPERTIES heap{};heap.Type=D3D12_HEAP_TYPE_DEFAULT;heap.CreationNodeMask=heap.VisibleNodeMask=1;D3D12_RESOURCE_DESC desc{};desc.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;desc.Width=bytes;desc.Height=1;desc.DepthOrArraySize=desc.MipLevels=1;desc.SampleDesc.Count=1;desc.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;desc.Flags=D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;gpu_test::hr(rig.device.p->CreateCommittedResource(&heap,D3D12_HEAP_FLAG_NONE,&desc,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,nullptr,IID_PPV_ARGS(output.out())),"Create WF query output");
        rig.begin();require(view->markUsed(rig.ticket()),"WF query actual fence rejected");ID3D12DescriptorHeap* heaps[]={b.descriptors};rig.commands.p->SetDescriptorHeaps(1,heaps);rig.commands.p->SetComputeRootSignature(root.p);rig.commands.p->SetPipelineState(pipeline.p);auto constants=b.constants(input.size(),tick);rig.commands.p->SetComputeRoot32BitConstants(0,28,constants.data(),0);rig.commands.p->SetComputeRootShaderResourceView(1,b.pageTable);rig.commands.p->SetComputeRootShaderResourceView(2,requests.p->GetGPUVirtualAddress());rig.commands.p->SetComputeRootUnorderedAccessView(3,output.p->GetGPUVirtualAddress());rig.commands.p->Dispatch((input.size()+63)/64,1,1);gpu_test::transition(rig.commands.p,output.p,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,D3D12_RESOURCE_STATE_COPY_SOURCE);rig.commands.p->CopyBufferRegion(read.p,0,output.p,0,bytes);rig.submit();
        D3D12_RANGE range{0,bytes};gpu_test::hr(read.p->Map(0,&range,&data),"Map completed WF validation");std::vector<f::GpuFieldAnswer> result(input.size());std::memcpy(result.data(),data,bytes);read.p->Unmap(0,&none);return result;
    }
};


void numeric(Rig& rig,unsigned ratio){
    auto p=quiet();p.dimensions={5,3,3};p.cellMetres=1.f/ratio;f::GpuLocalGrid grid{{1,2,3},1};const f::Cell origin{-3,-2,-1};p.originMetres={1-3*p.cellMetres,2-2*p.cellMetres,3-p.cellMetres};
    auto initial=s::initialState(p);for(unsigned i=0;i<initial.scalars.size();++i)initial.scalars[i]=(i%9)*.125f+.03125f;
    s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);std::string error;require(solver.setInputs(std::vector<s::CellInput>(initial.velocity.size()),error,&initial),error.c_str());rig.begin();require(solver.step(rig.commands.p,rig.ticket(),0,1.f/120,error),error.c_str());rig.submit();
    f::GpuLocalFields fields(rig.device.p,rig.fence.p,catalog(),{},grid);const auto spec=local(p,ratio,origin);f::GpuLocalHandle handle;require(fields.create(spec,handle,error),error.c_str());auto projection=project(rig,fields,handle,solver,1);auto actual=read(rig,projection);const auto b=projection->bindings();
    std::uint64_t input=0,loss=0;unsigned clamped=0;for(float value:initial.scalars){const unsigned quantized=unsigned(std::floor(value*256+.5f));input+=std::min(quantized,128u);if(quantized>128){++clamped;loss+=quantized-128;}}
    std::uint64_t reconstructed=0;unsigned at=0;for(int z=b.region.min.z;z<b.region.max.z;++z)for(int y=b.region.min.y;y<b.region.max.y;++y)for(int x=b.region.min.x;x<b.region.max.x;++x){
        long long integral=0;for(unsigned i=0;i<initial.scalars.size();++i){const int fx=origin.x+int(i%5),fy=origin.y+int(i/5%3),fz=origin.z+int(i/15);if(std::floor(double(fx)/ratio)==x&&std::floor(double(fy)/ratio)==y&&std::floor(double(fz)/ratio)==z)integral+=std::min(int(std::floor(initial.scalars[i]*256+.5f)),128);}
        const int expected=int(std::llround(double(integral)/(ratio*ratio*ratio)));require(actual.values[at++]==expected,"Coarse density differs from independent volume average");reconstructed+=std::uint64_t(expected)*ratio*ratio*ratio;++comparisons;
    }
    require(actual.input==input&&actual.reconstructed==reconstructed&&actual.residual==std::int64_t(input)-std::int64_t(reconstructed),"Projection integral/residual incorrect");require(actual.diagnostics[0]==45&&actual.diagnostics[2]==0&&actual.diagnostics[3]==clamped&&actual.diagnostics[8]==loss,"Fine quantization/clamp diagnostics incorrect");
    cases.push_back({{"case","density-volume-projection"},{"finePerWorld",ratio},{"inputIntegral",input},{"reconstructedIntegral",reconstructed},{"residual",actual.residual},{"clampLoss",loss}});projection.reset();fields.collect();require(fields.shutdown(error)&&solver.shutdown(error),error.c_str());++groups;
}
void worldReplacement(Rig& rig){
    auto p=quiet();auto c=catalog(1024);s::GpuSmokeFireSolver a(rig.device.p,rig.fence.p,p),b(rig.device.p,rig.fence.p,p);initialize(rig,a,p,.25f);initialize(rig,b,p,.5f);
    f::GpuLocalFields fields(rig.device.p,rig.fence.p,c);f::GpuLocalHandle ha,hb;std::string error;require(fields.create(local(p,2,{},1),ha,error)&&fields.create(local(p,2,{},2),hb,error),error.c_str());auto pa=project(rig,fields,ha,a,1),pb=project(rig,fields,hb,b,1);
    f::GpuVisualWorld world(rig.device.p,rig.fence.p,c);f::LeaseRequest request;request.region={{0,0,0},{2,2,2}};request.owner="smoke";request.channels={0};request.writable=true;request.maxPages=8;request.maxAgeTicks=20;auto wa=world.acquire(request),wb=world.acquire(request);request.writable=false;request.owner="reader";auto reader=world.acquire(request);require(wa.accepted&&wb.accepted&&reader.accepted,"WF leases rejected");
    auto commit=[&](f::Tick tick){rig.begin();require(world.commit(rig.commands.p,rig.ticket(),tick,error),error.c_str());rig.submit();world.collect();};
    require(world.publish(wa.lease,pa,1,1,error)==f::PublishResult::Accepted&&world.publish(wb.lease,pb,1,1,error)==f::PublishResult::Accepted,error.c_str());commit(1);auto old=world.view(reader.lease,error);require(!!old,error.c_str());Query query(rig);std::vector<f::GpuFieldQuery> points{{0,0,0,0,0,0,0,0}};
    auto sample=[&](const std::shared_ptr<f::GpuVisualView>& view,f::Tick tick,int expected,f::Status status=f::Status::Ok){auto results=query.run(rig,view,points,tick);if(results.size()==1&&(results[0].status!=unsigned(status)||results[0].value!=expected))std::cerr<<"WF tick="<<tick<<" actual="<<results[0].value<<" status="<<results[0].status<<" expected="<<expected<<'\n';require(results.size()==1&&results[0].status==unsigned(status)&&results[0].value==expected,"WF density replacement/query value incorrect");++comparisons;};sample(old,1,192);
    require(world.publish(wa.lease,pa,1,1,error)==f::PublishResult::Duplicate,"Duplicate state was not idempotent");std::vector<s::CellInput> inputs(64);for(auto& input:inputs)input.densityRate=30;require(a.setInputs(inputs,error),error.c_str());rig.begin();require(a.step(rig.commands.p,rig.ticket(),1,1.f/120,error),error.c_str());rig.submit();auto updated=project(rig,fields,ha,a,2);require(world.publish(wa.lease,updated,2,2,error)==f::PublishResult::Accepted,error.c_str());commit(2);auto current=world.view(reader.lease,error);require(!!current,error.c_str());sample(current,2,256);sample(old,1,192);
    require(world.withdraw(wa.lease,1,3,3,error)==f::PublishResult::Accepted,error.c_str());commit(3);auto remaining=world.view(reader.lease,error);require(!!remaining,error.c_str());sample(remaining,3,128);
    require(world.withdraw(wb.lease,2,2,4,error)==f::PublishResult::Accepted,error.c_str());commit(4);require(!world.sourceView("smoke",1).hasContribution&&!world.sourceView("smoke",2).hasContribution,"Final withdrawal retained source values");auto empty=world.view(reader.lease,error);require(!!empty,error.c_str());sample(empty,4,0,f::Status::Unavailable);sample(current,2,256);
    cases.push_back({{"case","actual-smoke-state-WF"},{"initialTwoSources",192},{"replacedNotAdded",256},{"oneWithdrawn",128},{"bothWithdrawn",0},{"oldSnapshotUnchanged",true}});
    old.reset();current.reset();remaining.reset();empty.reset();pa.reset();pb.reset();updated.reset();require(world.release(wa.lease,error)&&world.release(wb.lease,error)&&world.release(reader.lease,error),error.c_str());world.collect();require(world.stats().currentPages==0&&world.stats().accountedBytes==0,"Unleased world retained pages after readers retired");require(world.shutdown(error),error.c_str());fields.collect();require(fields.shutdown(error)&&a.shutdown(error)&&b.shutdown(error),error.c_str());++groups;
}
void admissionAndLifetime(Rig& rig){
    auto p=quiet();s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);initialize(rig,solver,p,.25f);f::GpuLocalLimits limits;limits.maxInputBatches=1;f::GpuLocalFields fields(rig.device.p,rig.fence.p,catalog(),limits);f::GpuLocalHandle h;std::string error;require(fields.create(local(p,2,{}),h,error),error.c_str());
    unsigned preparations=0;const auto good=s::densityFieldInput(solver);auto test=[&](f::GpuScalarInput in){const auto before=fields.stats();const auto original=in.prepareRead;in.prepareRead=[&](ID3D12GraphicsCommandList* list,std::uint64_t fence,std::string& why){++preparations;return original(list,fence,why);};require(!fields.replaceScalar(h,in,rig.commands.p,rig.ticket(),error)&&fields.stats().dispatches==before.dispatches&&fields.stats().heldInputReferences==before.heldInputReferences&&fields.inspect(h).version==0,"Invalid input recorded commands or mutated state");};
    rig.begin();auto bad=good;bad.dimensions.x++;test(bad);bad=good;bad.originMetres.x+=.01f;test(bad);bad=good;bad.cellMetres*=2;test(bad);bad=good;bad.offset=UINT32_MAX;test(bad);bad=good;bad.maximum=100000;test(bad);bad=good;bad.version=0;test(bad);bad=good;bad.lastFence=rig.ticket()+1;test(bad);bad=good;bad.sourceTick=UINT64_MAX;test(bad);
    gpu_test::Com<ID3D12Fence> other;gpu_test::hr(rig.device.p->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(other.out())),"Create mismatched timeline");bad=good;bad.timeline=other.p;test(bad);require(preparations==0,"Rejected input touched producer before admission");rig.submit();
    // A borrowed descriptor cannot silently read a newer ping-pong state.
    rig.begin();require(solver.step(rig.commands.p,rig.ticket(),1,1.f/120,error),error.c_str());require(!fields.replaceScalar(h,good,rig.commands.p,rig.ticket(),error)&&fields.stats().dispatches==0,"Stale borrowed solver descriptor was accepted");rig.submit();
    gpu_test::Com<ID3D12Fence> gate;gpu_test::hr(rig.device.p->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(gate.out())),"Create scalar gate");struct Release{ID3D12Fence* p;~Release(){p->Signal(1);}} release{gate.p};gpu_test::hr(rig.queue.p->Wait(gate.p,1),"Gate scalar import");
    rig.begin();require(fields.replaceScalar(h,s::densityFieldInput(solver),rig.commands.p,rig.ticket(),error),error.c_str());auto projection=fields.project(h,2,rig.commands.p,rig.ticket(),error);require(!!projection,error.c_str());const auto calls=fields.stats().dispatches;require(solver.step(rig.commands.p,rig.ticket(),2,1.f/120,error),error.c_str());const bool budgetRejected=!fields.replaceScalar(h,s::densityFieldInput(solver),rig.commands.p,rig.ticket(),error)&&fields.stats().dispatches==calls;rig.submit(false);
    const bool protectedBuffers=fields.stats().heldInputReferences==1&&!fields.shutdown(error)&&!solver.shutdown(error);gpu_test::hr(gate.p->Signal(1),"Release scalar gate");rig.wait();require(budgetRejected&&protectedBuffers,"Actual input fence/batch budget was not enforced");fields.collect();auto closedInput=s::densityFieldInput(solver);require(fields.stats().heldInputReferences==0&&solver.shutdown(error),"Completed source did not retire");rig.begin();const auto prior=fields.stats().dispatches;require(!fields.replaceScalar(h,closedInput,rig.commands.p,rig.ticket(),error)&&fields.stats().dispatches==prior,"Descriptor of a closed producer was not safely rejected");rig.submit();const auto result=read(rig,projection);require(std::all_of(result.values.begin(),result.values.end(),[](int value){return value==64;}),"Projection lost data after source shutdown");projection.reset();fields.collect();require(fields.shutdown(error),error.c_str());cases.push_back({{"case","admission-and-actual-fence"},{"noProducerCallsOnAdmissionFailure",true},{"heldReferencesWhileBlocked",1},{"staleBorrowRejected",true}});++groups;
}
void invalidGpuValues(Rig& rig){
    f::GpuLocalFields fields(rig.device.p,rig.fence.p,{{"density","kg/m^3","smoke",f::Domain::VisualReference,f::Merge::Sum,0,16,100}});auto p=quiet();p.dimensions={4,2,2};f::GpuLocalHandle h;std::string error;require(fields.create(local(p,2,{}),h,error),error.c_str());
    std::vector<float> payload(18,.25f);payload[2]=std::numeric_limits<float>::quiet_NaN();payload[3]=-1;payload[4]=2;gpu_test::Com<ID3D12Resource> upload,values;gpu_test::makeBuffer(rig.device.p,upload,payload.size()*4,D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ);gpu_test::makeBuffer(rig.device.p,values,payload.size()*4,D3D12_HEAP_TYPE_DEFAULT,D3D12_RESOURCE_STATE_COMMON);void* mapped=nullptr;D3D12_RANGE none{0,0};gpu_test::hr(upload.p->Map(0,&none,&mapped),"Map scalar fault fixture");std::memcpy(mapped,payload.data(),payload.size()*4);upload.p->Unmap(0,&none);
    rig.begin();f::GpuScalarInput input;input.values=values.p;input.timeline=rig.fence.p;input.offset=2;input.dimensions={4,2,2};input.cellMetres=.5f;input.maximum=1;input.version=1;input.lastFence=rig.ticket();input.prepareRead=[&](ID3D12GraphicsCommandList* list,std::uint64_t,std::string&){gpu_test::transition(list,values.p,D3D12_RESOURCE_STATE_COMMON,D3D12_RESOURCE_STATE_COPY_DEST);list->CopyBufferRegion(values.p,0,upload.p,0,payload.size()*4);gpu_test::transition(list,values.p,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);return true;};
    require(fields.replaceScalar(h,input,rig.commands.p,rig.ticket(),error),error.c_str());auto projection=fields.project(h,1,rig.commands.p,rig.ticket(),error);require(!!projection,error.c_str());rig.submit();auto out=read(rig,projection);require(out.diagnostics[2]==3&&out.diagnostics[0]==13&&out.diagnostics[3]==13&&out.diagnostics[8]==117&&out.input==208,"Invalid scalar cells or clamp loss were not diagnosed");projection.reset();fields.collect();require(fields.shutdown(error),error.c_str());++groups;
}
