int main(int argc,char** argv){try{std::string adapter;if(argc==3&&std::string(argv[1])=="--adapter")adapter=argv[2];else if(argc!=1)throw std::runtime_error("Usage: native_smoke_fields_tests [--adapter substring]");Rig rig(adapter);require(rig.debug,"Actual validation layer unavailable");for(unsigned ratio:{1u,2u,4u,8u,16u})numeric(rig,ratio);worldReplacement(rig);admissionAndLifetime(rig);invalidGpuValues(rig);const auto errors=rig.debugErrors();require(errors==0,"Smoke field D3D12 errors");std::cout<<nlohmann::json{{"schema","nativegpu.smoke-fields-evidence/1"},{"ok",true},{"groups",groups},{"checks",checks},{"comparisons",comparisons},{"cases",cases},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"runtimeReadback",false},{"scope","Actual GPU solver density -> immutable LEF projection -> visual WF replace/query/withdraw. No renderer coverage switching, temperature merge, full D/B or A-G acceptance."}}.dump()<<'\n';}catch(const std::exception& ex){std::cerr<<"Smoke fields failed after "<<checks<<" checks: "<<ex.what()<<'\n';return 1;}}
